\question{1}{8} Simplify each of the following expressions. Show your working clearly.

\begin{subparts}
  \item Convert each of the following mixed numbers into an improper fraction.
    \begin{subpartsii}
      \item $2\dfrac{3}{5}$
      \item $-3\dfrac{1}{4}$
    \end{subpartsii}

  \item Convert each of the following decimals into a fraction in its simplest form.
    \begin{subpartsii}
      \item $0.45$
      \item $2.125$
    \end{subpartsii}

  \item Evaluate $\left(2\dfrac{1}{2} - 4\dfrac{3}{4}\right) \times \left(-1\dfrac{1}{3}\right)$. Express your answer as a mixed number.

  \item Evaluate $\dfrac{3}{5} - 0.4 + \left(-1\dfrac{2}{3}\right) \div 2\dfrac{1}{2}$. Express your answer as a fraction in simplest form.
\end{subparts}

\finishquestion\answerlines{15}

\question{1}{8} Find the values of the following expressions. Show your working clearly.

\begin{subparts}
  \item Evaluate $\left(3\dfrac{1}{4} - 4\dfrac{5}{6}\right) \div \left(-1\dfrac{1}{2}\right)$. Express your answer as a mixed number in simplest form.

  \item Evaluate $\left(0.45 - \dfrac{3}{4}\right) \times \left(-2\dfrac{2}{5}\right)$. Express your answer as a fraction in simplest form.
\end{subparts}

\finishquestion\answerlines{15}

\question{1}{8}

\begin{subparts}
  \item $\left(2\dfrac{1}{4} - 3\dfrac{5}{6}\right) \div \left(-\dfrac{4}{9}\right) + (-1.25) \times 1\dfrac{3}{5}$

  \item $\left(0.35 + \dfrac{3}{4}\right) \times \left(-2\dfrac{2}{3}\right) - \dfrac{5}{12} \div \left(-\dfrac{5}{9}\right)$
\end{subparts}

\finishquestion\answerlines{18}

% ============================================================
% style.tex - Shared preamble, macros and layout for the
% MARKING SCHEME.
% Mirrors the question paper's fonts and base layout so the
% scheme reads as a companion document, not a different one.
% ============================================================

% Same geometry as the question paper (content pages):
% top=25mm, bottom=22mm, left=25mm, right=22mm.
\usepackage[a4paper,top=25mm,bottom=22mm,left=25mm,right=22mm,
            headsep=5mm,footskip=0mm]{geometry}
\usepackage{tikz}
\usetikzlibrary{calc}
\usepackage{array}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\usepackage{enumitem}
\usepackage{fancyhdr}
\usepackage{helvet}
\usepackage{mathptmx}  % Times New Roman for text and math
\usepackage{atbegshi}

% ---- Centralised customisation settings ----
\input{config}

% ------------------------------------------------------------
% Marking scheme step row.
% Usage:
%   \msstep{1 + 1}{1M}      % left = solution step, right = mark
%   \msans{= 2}{1A}         % final answer variant (same layout)
%
% The table is two columns, width ratio 7:3. The right column is
% right-aligned. No vertical borders, matching the look of a
% traditional pen-and-paper marking scheme.
% ------------------------------------------------------------
\newcommand{\msstep}[2]{%
  \noindent\begin{tabular}{@{}p{0.70\dimexpr\linewidth\relax}@{\hspace{6pt}}p{0.30\dimexpr\linewidth\relax}@{}}
  $#1$ & \hfill\textbf{#2}\tabularnewline
  \end{tabular}\par\vspace{2pt}%
}

% ------------------------------------------------------------
% Marks badge for the section header (e.g. "Question 1 (8 marks)")
% ------------------------------------------------------------
\newcommand{\qms}[1]{\textnormal{(#1 marks)}}

% ------------------------------------------------------------
% Page header bar — "MARKING SCHEME" left, paper title right.
% Same font size as the question paper footer.
% ------------------------------------------------------------
\pagestyle{fancy}
\fancyhf{}
\renewcommand{\headrulewidth}{0pt}
\fancyhead[L]{\fontsize{11pt}{11pt}\selectfont\bfseries MARKING SCHEME}
\fancyhead[R]{\fontsize{11pt}{11pt}\selectfont\bfseries\PaperFooterCode}
\fancyfoot[C]{\fontsize{11pt}{11pt}\selectfont\thepage}
\fancyheadoffset[L]{0mm}
\fancyfootoffset[L]{0mm}

% ------------------------------------------------------------
% Section header: same look as the question paper
% ------------------------------------------------------------
\newcommand{\sectionheader}[1]{%
  \vspace*{0mm}
  \noindent\textbf{Section #1}\par
  \vspace{1mm}
}

% ------------------------------------------------------------
% Question header in the marking scheme.
% Prints "1. (8 marks)" — the question number followed by the
% marks badge. The question text itself is typeset by the
% caller on the next line.
% ------------------------------------------------------------
\newcommand{\msquestion}[2]{%
  \vspace{5mm}%
  \noindent\textbf{#1.}\hspace{0.5em}\textbf{#2 marks}\par
}

% ------------------------------------------------------------
% Subpart heading, mirrors subparts in the question paper.
% (a), (b), (c), (d) inline with the question number.
% ------------------------------------------------------------
\newcounter{msSub}
\newenvironment{subparts}[1][1]{%
  \setcounter{msSub}{0}%
  \par\vspace{2pt}%
  \bgroup
  \let\olditem\item
  \def\item{\par\noindent\hspace*{2em}\stepcounter{msSub}(\alph{msSub})~}%
}{%
  \egroup
  \par\vspace{2pt}%
}

\newcounter{msSubii}
\newenvironment{subpartsii}[1][1]{%
  \setcounter{msSubii}{#1}%
  \addtocounter{msSubii}{-1}%
  \par\vspace{2pt}%
  \bgroup
  \let\olditem\item
  \def\item{\par\noindent\hspace*{3em}\stepcounter{msSubii}(\roman{msSubii})~}%
}{%
  \egroup
  \par\vspace{2pt}%
}

% ============================================================
% config.tex - CENTRALISED CUSTOMISATION SETTINGS for the
% MARKING SCHEME. Mirrors the question paper where possible.
% ============================================================

% ---- Paper metadata ----
\newcommand{\PaperYear}{2026-2027}
\newcommand{\PaperStartYear}{2026}
\newcommand{\PaperCode}{MATH S.1}
\newcommand{\PaperSubjLine}{Mock}
\newcommand{\PaperType}{FIRST TEST}
\newcommand{\PaperTotalMarks}{60}
\newcommand{\PaperTime}{40 minutes}

% Code printed in the bottom-left of every page.
\newcommand{\PaperFooterCode}{HKTA THMSS MATH S.1 First Test \PaperYear}

% ---- Cover-style metadata (kept for consistency with QP) ----
\newcommand{\CoverAuthority}{TANG HIN MEMORIAL SECONDARY SCHOOL}
\newcommand{\CoverExamName}{SECONDARY 1 FIRST TEST \PaperYear}
\newcommand{\CoverTitle}{MATHEMATICS FIRST TEST}
\newcommand{\CoverSubtitle}{Marking Scheme}
\newcommand{\CoverLanguageNote}{This marking scheme must be used in conjunction with the question paper.}

% ---- Copyright notice ----
\newcommand{\CoverCopyright}{%
  \textcopyright\ THMSS All rights reserved \PaperStartYear.%
}

% ============================================================
% main.tex - Marking scheme top-level driver file.
% Compile with: pdflatex -interaction=nonstopmode main.tex
% ============================================================

\documentclass[11pt,a4paper]{article}

\input{style}

\begin{document}

  % Cover-ish title page (simple title block + paper metadata)
  \begin{titlepage}
  \thispagestyle{fancy}
  \begin{center}
    \vspace*{15mm}
    {\fontsize{10pt}{12pt}\selectfont \CoverAuthority\par}
    \vspace{1.5mm}
    {\fontsize{10pt}{12pt}\selectfont \CoverExamName\par}
    \vspace{1cm}
    {\fontsize{18pt}{20pt}\selectfont\bfseries \CoverTitle\par}
    \vspace{5mm}
    {\fontsize{13pt}{15pt}\selectfont\bfseries \CoverSubtitle\par}
    \vspace{10mm}
    {\fontsize{11pt}{13pt}\selectfont Total marks: \PaperTotalMarks \quad | \quad
     Time allowed: \PaperTime\par}
    \vspace{20mm}
    {\fontsize{10pt}{12pt}\selectfont
      \itshape\CoverLanguageNote\par}
    \vspace*{\fill}
    {\fontsize{9.5pt}{11.5pt}\selectfont
      \CoverCopyright\par}
    \vspace{1cm}
  \end{center}
  \end{titlepage}

  % Rest of the marking scheme content
  \setcounter{page}{2}
  \input{content}

\end{document}

% ============================================================
% content.tex - Marking scheme content for F.1 First Test.
% Edit individual question schemes in the questions/ folder.
