% ============================================================
% ms-q1.tex - Marking scheme for Question 1 (8 marks)
% Question text (verbatim from q1.tex):
%   Evaluate each of the following expressions. Show your
%   working clearly.
%   (a) (2 1/4 - 3 5/6) ÷ (-4/9) + (-1.25) × 1 3/5
%   (b) (0.35 + 3/4) × (-2 2/3) - 5/12 ÷ (-5/9)
% ============================================================

\msquestion{1}{8}

\noindent Evaluate each of the following expressions. Show your working clearly.

\begin{subparts}
  \item
  \msstep{\left(2\dfrac{1}{4} - 3\dfrac{5}{6}\right) \div \left(-\dfrac{4}{9}\right) + (-1.25) \times 1\dfrac{3}{5}}{}
  \msstep{= \left(\dfrac{9}{4} - \dfrac{23}{6}\right) \div \left(-\dfrac{4}{9}\right) + \left(-\dfrac{5}{4}\right) \times \dfrac{8}{5}}{1M}
  \msstep{= \left(-\dfrac{19}{12}\right) \div \left(-\dfrac{4}{9}\right) + (-2)}{1M}
  \msstep{= \left(-\dfrac{19}{12}\right) \times \left(-\dfrac{9}{4}\right) + (-2) = \dfrac{57}{16} + (-2)}{1M}
  \msstep{= \dfrac{57}{16} - \dfrac{32}{16} = \dfrac{25}{16} = 1\dfrac{9}{16}}{1A}

  \item
  \msstep{\left(0.35 + \dfrac{3}{4}\right) \times \left(-2\dfrac{2}{3}\right) - \dfrac{5}{12} \div \left(-\dfrac{5}{9}\right)}{}
  \msstep{= \left(\dfrac{7}{20} + \dfrac{15}{20}\right) \times \left(-\dfrac{8}{3}\right) - \dfrac{5}{12} \div \left(-\dfrac{5}{9}\right)}{1M}
  \msstep{= \dfrac{11}{10} \times \left(-\dfrac{8}{3}\right) - \dfrac{5}{12} \times \left(-\dfrac{9}{5}\right) = -\dfrac{44}{15} + \dfrac{3}{4}}{1M}
  \msstep{= -\dfrac{176}{60} + \dfrac{45}{60}}{1M}
  \msstep{= -\dfrac{131}{60} = -2\dfrac{11}{60}}{1A}
\end{subparts}

% ============================================================
% ms-q1.tex - Marking scheme for Question 1 (8 marks)
% ============================================================

\msquestion{1}{8}

\noindent Evaluate each of the following expressions. Show your working clearly.

\begin{subparts}
  \item
  \msstep{= \left(\dfrac{9}{4} - \dfrac{23}{6}\right) \div \left(-\dfrac{4}{9}\right) + \left(-\dfrac{5}{4}\right) \times \dfrac{8}{5}}{1M}
  \msstep{= \left(-\dfrac{19}{12}\right) \div \left(-\dfrac{4}{9}\right) + (-2)}{1M}
  \msstep{= \left(-\dfrac{19}{12}\right) \times \left(-\dfrac{9}{4}\right) + (-2) = \dfrac{57}{16} + (-2)}{1M}
  \msstep{= \dfrac{57}{16} - \dfrac{32}{16} = \dfrac{25}{16} = 1\dfrac{9}{16}}{1A}

  \item
  \msstep{= \left(\dfrac{7}{20} + \dfrac{15}{20}\right) \times \left(-\dfrac{8}{3}\right) - \dfrac{5}{12} \div \left(-\dfrac{5}{9}\right)}{1M}
  \msstep{= \dfrac{11}{10} \times \left(-\dfrac{8}{3}\right) - \dfrac{5}{12} \times \left(-\dfrac{9}{5}\right) = -\dfrac{44}{15} + \dfrac{3}{4}}{1M}
  \msstep{= -\dfrac{176}{60} + \dfrac{45}{60}}{1M}
  \msstep{= -\dfrac{131}{60} = -2\dfrac{11}{60}}{1A}
\end{subparts}

% ============================================================
% ms-q2.tex - Marking scheme for Question 2 (5 marks)
% ============================================================

\msquestion{2}{5}

\begin{subparts}
  \item
  ``Divide the sum of positive $9$ and negative $3$ by the product of $2$ and $3$''
  \msstep{= \dfrac{(+9) + (-3)}{2 \times 3}}{1M}
  \msstep{= \dfrac{+6}{+6}}{1M}
  \msstep{= +1}{1A}

  \item
  \msstep{(i) \ 165 + (+5) = 170 \text{ cm}}{1A}
  \msstep{(ii) \ 165 + (-7.5) = 157.5 \text{ cm}}{1A}
\end{subparts}

% ============================================================
% ms-q3.tex - Marking scheme for Question 3 (5 marks)
% ============================================================

\msquestion{3}{5}

\noindent Simplify the following expressions.

\begin{subparts}
  \item
  \msstep{= 1 + 8n \div 4 - 3 + 2a}{1M}
  \msstep{= 1 + 2n - 3 + 2a}{1M}
  \msstep{= -2 + 2n + 2a}{1A}

  \item
  \msstep{= m \times (-n) \times m + (-1) \times 5m}{1M}
  \msstep{= -mn \times m + (-5m)}{1M}
  \msstep{= -m^2 n - 5m}{1A}
\end{subparts}

% ============================================================
% ms-q4.tex - Marking scheme for Question 4 (4 marks, 4 subparts)
% ============================================================

\msquestion{4}{4}

\noindent In each of the following sequences, write down the next term.

\begin{subparts}
  \item
  \msstep{\text{The common ratio } r = -\dfrac{1}{2}}{1M}
  \msstep{3 \times \left(-\dfrac{1}{2}\right) = -\dfrac{3}{2}}{1A}

  \item
  \msstep{\text{Second differences are constant } (+4, +6, +8)}{1M}
  \msstep{4 + 10 = 14}{1A}

  \item
  \msstep{\text{Common difference } d = \dfrac{2}{3}}{1M}
  \msstep{6 + \dfrac{2}{3} = \dfrac{20}{3}}{1A}

  \item
  \msstep{\text{Common difference } d = -\dfrac{2}{3}}{1M}
  \msstep{-\dfrac{4}{3} + \left(-\dfrac{2}{3}\right) = -2}{1A}
\end{subparts}

% ============================================================
% ms-q5.tex - Marking scheme for Question 5 (4 marks)
% Divisibility checks; each tick in the correct box earns 1 mark.
% ============================================================

\msquestion{5}{4}

\noindent For each number, tick the box if it is divisible by the
corresponding divisor.

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\textbf{Number} & \textbf{Divisible by 3} & \textbf{Divisible by 4} & \textbf{Divisible by 6} & \textbf{Divisible by 9} \\
\hline
$7546$    &    &    &    &    \\ \hline
$2949120$ & $\checkmark$ & $\checkmark$ & $\checkmark$ & $\checkmark$ \\ \hline
$949500$  & $\checkmark$ & $\checkmark$ & $\checkmark$ & $\checkmark$ \\ \hline
$5000080$ &               & $\checkmark$ &               &               \\ \hline
\end{tabular}
\end{center}

\vspace{2mm}
\noindent\textbf{Mark allocation (one mark per correct tick):}
\begin{itemize}[leftmargin=2em,itemsep=2pt]
  \item $7546$: none $\longrightarrow 0$ marks.
  \item $2949120$: divisible by $3, 4, 6, 9$ $\longrightarrow 1 + 1 + 1 + 1 = 4$ marks.
  \item $949500$: divisible by $3, 4, 6, 9$ $\longrightarrow 4$ marks.
  \item $5000080$: divisible by $4$ only $\longrightarrow 1$ mark.
\end{itemize}

% ============================================================
% ms-q5.tex - Marking scheme for Question 5 (4 marks)
% Divisibility checks; one mark per correctly completed row.
% ============================================================

\msquestion{5}{4}

\noindent For each number, tick the box if it is divisible by the
corresponding divisor. (One mark per row that is completed
correctly, i.e. all $\checkmark$s in the correct boxes and none
elsewhere.)

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\textbf{Number} & \textbf{Divisible by 3} & \textbf{Divisible by 4} & \textbf{Divisible by 6} & \textbf{Divisible by 9} \\
\hline
$7546$    &               &               &               &               \\ \hline
$2949120$ & $\checkmark$  & $\checkmark$  & $\checkmark$  & $\checkmark$  \\ \hline
$949500$  & $\checkmark$  & $\checkmark$  & $\checkmark$  & $\checkmark$  \\ \hline
$5000080$ &               & $\checkmark$  &               &               \\ \hline
\end{tabular}
\end{center}

\vspace{2mm}
\noindent\textbf{Row-by-row justification:}
\begin{itemize}[leftmargin=2em,itemsep=2pt]
  \item $7546$: digit sum $7+5+4+6 = 22$ (not divisible by $3, 9$); last two digits $46$ (not divisible by $4$); not even (not divisible by $6$). \emph{All four boxes blank.}
  \item $2949120$: digit sum $= 27$ (divisible by $3, 9$); last two digits $20$ (divisible by $4$); ends in $0$ so even and divisible by $3$, hence by $6$. \emph{All four boxes ticked.}
  \item $949500$: digit sum $= 27$ (divisible by $3, 9$); last two digits $00$ (divisible by $4$); ends in $0$ so even and divisible by $3$, hence by $6$. \emph{All four boxes ticked.}
  \item $5000080$: digit sum $= 13$ (not divisible by $3, 9$); last two digits $80$ (divisible by $4$); even but not divisible by $3$ (not divisible by $6$). \emph{Only the ``divisible by 4'' box is ticked.}
\end{itemize}

% ============================================================
% ms-q6.tex - Marking scheme for Question 6 (10 marks)
% ============================================================

\msquestion{6}{10}

\noindent Solve the following equations.

\begin{subparts}
  \item
  \msstep{4 \times \dfrac{x}{4} = 4 \times 6}{1M}
  \msstep{x = 24}{1A}

  \item
  \msstep{6 \times \dfrac{5x}{6} = 6 \times 3}{1M}
  \msstep{5x = 18 \quad \Rightarrow \quad x = \dfrac{18}{5}}{1A}

  \item
  \msstep{\dfrac{8}{x} = 10 + \dfrac{18}{4} = \dfrac{20}{2} + \dfrac{9}{2} = \dfrac{29}{2}}{1M}
  \msstep{8 \times 2 = 29 \times x}{1M}
  \msstep{x = \dfrac{16}{29}}{1A}

  \item
  \msstep{7(-9 + x) = 2(5 - x)}{1M}
  \msstep{-63 + 7x = 10 - 2x \quad \Rightarrow \quad 9x = 73}{1M}
  \msstep{x = \dfrac{73}{9}}{1A}
\end{subparts}

% ============================================================
% ms-q7.tex - Marking scheme for Question 7 (8 marks)
%
% NOTE: The question paper has the Mystery and Romance book
% counts marked as ``?'' — the original numbers appear to be
% missing. The marking scheme below assumes the intended
% problem is the standard HCF-of-three-numbers variant that
% fits the wording, and allocates marks accordingly. Replace
% the bracketed placeholders with the actual counts once the
% question paper is finalised.
% ============================================================

\msquestion{7}{8}

\begin{center}
\begin{tabular}{|l|c|}
\hline
\textbf{Genres} & \textbf{Number of books} \\
\hline
Science Fiction & $1824$ \\
Mystery         & [value] \\
Romance         & [value] \\
\hline
\end{tabular}
\end{center}

\begin{subparts}
  \item
  \msstep{\text{Total number of books} = 1824 + [\text{Mystery}] + [\text{Romance}].}{1M}
  \msstep{\text{If the total is divisible by } 8, \text{ then YES; otherwise NO.}}{1A}

  \item
  \msstep{\text{We find the highest common factor (HCF) of } 1824, [\text{Mystery}], [\text{Romance}].}{1M}
  \msstep{\text{By prime factorisation / successive division, HCF } = H.}{1M}
  \msstep{\text{The maximum number of books per shelf is } H.}{1A}

  \item
  \msstep{\text{Number of shelves per genre} = \dfrac{\text{count per genre}}{H}.}{1M}
  \msstep{\text{Total shelves} = \dfrac{1824}{H} + \dfrac{[\text{Mystery}]}{H} + \dfrac{[\text{Romance}]}{H}.}{1M}
  \msstep{\text{Substituting } H \text{ gives the final number of shelves.}}{1A}
\end{subparts}

% ============================================================
% ms-q8.tex - Marking scheme for Question 8 (8 marks)
% ============================================================

\msquestion{8}{8}

\begin{center}
\begin{tabular}{|c|c|}
\hline
\textbf{Time} & \textbf{Temperature change ($^\circ$C)} \\
\hline
2 p.m.\ to 3 p.m. & $-1.4$ \\
3 p.m.\ to 4 p.m. & $+0.6$ \\
4 p.m.\ to 5 p.m. & $-1.2$ \\
\hline
\end{tabular}
\end{center}

\begin{subparts}
  \item
  \msstep{(i) \ 25 + (-1.4) = 23.6^\circ\text{C} \quad \text{(temperature at 3 p.m.)}}{1A}
  \msstep{(ii) \ 23.6 + 0.6 = 24.2^\circ\text{C} \quad \text{(temperature at 4 p.m.)}}{1A}
  \msstep{(iii) \ 24.2 + (-1.2) = 23.0^\circ\text{C} \quad \text{(temperature at 5 p.m.)}}{1A}

  \item
  \msstep{\text{Total change from 5 p.m. to 7 p.m.} = 22.6 - 23 = -0.4^\circ\text{C}}{1M}
  \msstep{\text{Change per hour} = -0.4 \div 2 = -0.2^\circ\text{C}}{1M}
  \msstep{\text{Temperature at 6 p.m.} = 23 + (-0.2) = 22.8^\circ\text{C}}{1M}
  \msstep{\text{Since } 22.8^\circ\text{C} < 25^\circ\text{C}, \text{ Candy is wrong. The temperature at 6 p.m. is lower than at 2 p.m.}}{1A}
\end{subparts}

% ============================================================
