% traditional pen-and-paper marking scheme.
% ------------------------------------------------------------
\newcommand{\msstep}[2]{%
  \par\noindent
  \begin{tabular}{@{}p{0.70\linewidth}@{\hspace{4pt}}p{0.30\linewidth}@{}}
