\newcommand{\adjustlinewidth}{%
  \setlength{\linewidth}{\dimexpr\linewidth - 2em\relax}%
}
\newcommand{\adjustlinewidthii}{%
  \setlength{\linewidth}{\dimexpr\linewidth - 3em\relax}%
}

% ------------------------------------------------------------
