% ------------------------------------------------------------
% Marking scheme subpart.
%
% Each subpart is rendered as its OWN framed table with a
% middle vertical strip (no horizontal rules between rows).
% Marks in the right column are LEFT-aligned.
%
% Usage:
%   \begin{mspart}{(a)}
%     \msstep{1 + 1}{1M}    % adds a row inside the table
%     \msstep{= 2}{1A}
%   \end{mspart}
%
% Visual layout (no horizontal lines, just outer + middle vrule):
%   | (a) (header, spans both columns)        |
